head.script:
(function () {
  var XHTML_NS = "http://www.w3.org/1999/xhtml";
  var foreignObject = document.querySelector("foreignObject");
  if (!foreignObject) return;
  var root = foreignObject.firstElementChild;
  if (!root) return;
  var origCE = document.createElement.bind(document);
  var origCENS = document.createElementNS.bind(document);

  try {
    Object.defineProperty(document, "head", {
      get: function () { return root.querySelector("head"); },
      configurable: true
    });
    Object.defineProperty(document, "body", {
      get: function () { return root.querySelector("body"); },
      configurable: true
    });
    Object.defineProperty(document, "documentElement", {
      get: function () { return root; },
      configurable: true
    });
  } catch (_) {}

  document.createElement = function (tag, options) {
    if (typeof tag === "string") {
      try { return origCENS(XHTML_NS, tag, options); }
      catch (_) { return origCENS(XHTML_NS, tag); }
    }
    return origCE(tag, options);
  };

  document.createElementNS = function (ns, tag, options) {
    if (ns == null || ns === XHTML_NS) {
      try { return origCENS(XHTML_NS, tag, options); }
      catch (_) { return origCENS(XHTML_NS, tag); }
    }
    try { return origCENS(ns, tag, options); }
    catch (_) { return origCENS(ns, tag); }
  };

  try {
    Object.defineProperty(document, "getElementById", {
      value: function (id) {
        var safe = String(id).replace(/["\\]/g, "\\$&");
        return root.querySelector('[id="' + safe + '"]');
      },
      configurable: true,
      writable: true
    });
  } catch (_) {}

  try {
    document.querySelector = function (selector) {
      try { return root.querySelector(selector) || origQS(selector); }
      catch (_) { return origQS(selector); }
    };
    var origQS = document.querySelector.bind(document);
  } catch (_) {}
})();

body.script:
// Synnical OS Desktop Controller
(function() {
  const days = ['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'];
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const dayHeaders = ['M','T','W','T','F','S','S'];

  // Dock icons data
  const dockApps = [
    { name: 'Synnical', icon: '<rect width="34" height="34" rx="8" fill="#0a0a0a"/><rect x="1" y="1" width="32" height="32" rx="7" fill="none" stroke="#ec4899" stroke-width="1.5"/><text x="17" y="24" text-anchor="middle" font-family="Arial Black" font-size="18" font-weight="900" fill="#ec4899">S</text>' },
    { name: 'Search', icon: '<circle cx="17" cy="17" r="8" stroke="white" stroke-width="2" fill="none"/><path d="M23 23l4 4" stroke="white" stroke-width="2"/>' },
    { name: 'Files', icon: '<path d="M7 10h14l3 4v12H7z" fill="#FDB300"/><path d="M7 14h17v12H7z" fill="#F5A623" opacity="0.8"/>' },
    { name: 'Browser', icon: '<circle cx="17" cy="17" r="16" fill="#4285F4"/><circle cx="17" cy="17" r="6" fill="white"/>' },
    { name: 'VS Code', icon: '<rect width="34" height="34" rx="8" fill="#007ACC"/><path d="M11 11l7 6.5-7 6.5M19 11l7 6.5-7 6.5" stroke="white" stroke-width="2" fill="none"/>' },
    { name: 'Discord', icon: '<circle cx="17" cy="17" r="16" fill="#5865F2"/><circle cx="12" cy="14" r="3" fill="white"/><circle cx="22" cy="14" r="3" fill="white"/>' },
    { name: 'Spotify', icon: '<circle cx="17" cy="17" r="16" fill="#1DB954"/><path d="M10 13c4-2 10-2 14 0M10 17c4-1.5 10-1.5 14 0M10 21c4-1 10-1 14 0" stroke="black" stroke-width="2" fill="none"/>' },
    { name: 'Terminal', icon: '<rect width="34" height="34" rx="8" fill="#1E1E1E"/><path d="M10 12l5 4-5 4M18 20h5" stroke="#4EC9B0" stroke-width="1.5" fill="none"/>' },
    { name: 'Notes', icon: '<rect width="34" height="34" rx="8" fill="#FEF08A" stroke="#EAB308"/><line x1="10" y1="12" x2="24" y2="12" stroke="#854D0E"/><line x1="10" y1="17" x2="24" y2="17" stroke="#854D0E"/><line x1="10" y1="22" x2="19" y2="22" stroke="#854D0E"/>' },
  ];

  // Update clock
  function updateClock() {
    const now = new Date();

    document.getElementById('day-name').textContent = days[now.getDay()];
    document.getElementById('time-main').textContent = 
      String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
    document.getElementById('time-sec').textContent = String(now.getSeconds()).padStart(2,'0');
    document.getElementById('full-date').textContent = 
      days[now.getDay()] + ', ' + months[now.getMonth()] + ' ' + now.getDate() + ', ' + now.getFullYear();

    document.getElementById('w-date-day').textContent = now.getDate();
    document.getElementById('w-date-month').textContent = months[now.getMonth()];
    document.getElementById('w-date-year').textContent = now.getFullYear();
    document.getElementById('notes-time').textContent = new Date().toLocaleString();

    document.getElementById('cal-header').textContent = 
      months[now.getMonth()].slice(0,3).toUpperCase() + ' • ' + now.getFullYear();

    buildCalendar(now);
  }

  // Build calendar
  function buildCalendar(date) {
    const grid = document.getElementById('cal-grid');
    if (!grid) return;

    const firstDay = new Date(date.getFullYear(), date.getMonth(), 1).getDay();
    const daysInMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    const today = date.getDate();

    let html = dayHeaders.map(d => `<span class="cal-day-header">${d}</span>`).join('');

    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    for (let i = 0; i < startOffset; i++) html += '<span></span>';
    for (let i = 1; i <= daysInMonth; i++) {
      html += `<span class="cal-day${i === today ? ' today' : ''}">${i}</span>`;
    }

    grid.innerHTML = html;
  }

  // Build dock
  function buildDock() {
    const dock = document.getElementById('dock');
    if (!dock) return;

    let html = '';
    dockApps.forEach(app => {
      html += `<button class="dock-item" title="${app.name}">
        <svg viewBox="0 0 34 34">${app.icon}</svg>
      </button>`;
    });

    // Separator + Trash
    html += `<div class="dock-separator"></div>`;
    html += `<button class="dock-item" title="Trash">
      <svg viewBox="0 0 34 34"><path d="M7 10h20M19 10v18a2 2 0 01-2 2H13a2 2 0 01-2-2V10m3 0V8a2 2 0 012-2h4a2 2 0 012 2v2" stroke="white" stroke-width="1.5" fill="none"/></svg>
    </button>`;

    dock.innerHTML = html;
  }

  // Init
  updateClock();
  buildDock();
  setInterval(updateClock, 1000);

  console.log('%c✨ Synnical OS Desktop Loaded', 'color: #ec4899; font-size: 14px; font-weight: bold;');
})();
